"""Generate rtl/kwt_rsqrt_lut.v: LUT[k] ~= 65536/sqrt((k+0.5)*2^17)."""
import os
import numpy as np

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
OUT = os.path.join(ROOT, 'rtl', 'kwt_rsqrt_lut.v')

vals = [int(round(65536.0 / np.sqrt((k + 0.5) * 1024))) for k in range(256)]
vals = [max(1, min(1 << 24, v)) for v in vals]

lines = [
    '`timescale 1ns / 1ps',
    '// AUTO-GENERATED by tools/gen_rsqrt_lut.py -- do not edit',
    'module kwt_rsqrt_lut (',
    '    input  wire [7:0]  idx,',
    '    output reg  [31:0] val',
    ');',
    '    always @(*) begin',
    '        case (idx)',
]
for i, v in enumerate(vals):
    lines.append("            8'd%-3d: val = 32'd%d;" % (i, v))
lines += ["            default: val = 32'd1;", '        endcase', '    end', 'endmodule', '']

with open(OUT, 'w', encoding='ascii', newline='\n') as f:
    f.write('\n'.join(lines))
print('wrote %s' % OUT)
print('LUT[0]=%d LUT[1]=%d LUT[142]=%d LUT[255]=%d' % (vals[0], vals[1], vals[142], vals[255]))
